///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            await scwin.fnSearchInit();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.fnDetailClose();
    $c.util.getComponent("dma_fnFileDownReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnFileDownReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnFileDownReq").set("method", "listingForeignCompanyList");
    $c.util.getComponent("dma_fnFileDownReq").set("forward", "miscellaneousDataList");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack1
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack1 = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch1 = async function () {
    /* sdd-asis-lifecycle:begin fnSearch1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnFileDownReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnFileDownReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDetailView
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_contnId
 * @returns
 * @hidden N
*/
scwin.fnDetailView = async function (ipt_contnId) {
    /* sdd-asis-lifecycle:begin fnDetailView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("detailContents").setStyle("display", "");
    $c.util.getComponent("dma_fnFileDownReq").set("contnId", ipt_contnId);
    $c.util.getComponent("dma_fnFileDownReq").set("method", "listingForeignCompanyDetail");
    $c.util.getComponent("dma_fnFileDownReq").set("forward", "miscellaneousDataDetail");
    await scwin.tx_fnDetailView_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack2
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack2 = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#detailContents").empty().append(data);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDetailClose
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDetailClose = function () {
    /* sdd-asis-lifecycle:begin fnDetailClose — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#detailContents").empty();
    $c.util.getComponent("detailContents").setStyle("display", "none");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnFileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_resoroomId ipt_attachSeq ipt_attachFileNm
 * @returns
 * @hidden N
*/
scwin.fnFileDown = async function (ipt_resoroomId, ipt_attachSeq, ipt_attachFileNm) {
    /* sdd-asis-lifecycle:begin fnFileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnFileDownReq").set("method", "downloadCorpReportEtc");
    $c.util.getComponent("dma_fnFileDownReq").set("resoroomId", ipt_resoroomId);
    $c.util.getComponent("dma_fnFileDownReq").set("attachSeq", ipt_attachSeq);
    $c.util.getComponent("dma_fnFileDownReq").set("attachFileNm", ipt_attachFileNm);
    await scwin.tx_fnFileDown();
    /* sdd-asis-lifecycle:end */
};
